from pipeline.steps import Squeeze, Strip, Truncate, Upper

BARE_STEPS = {"upper": Upper(), "strip": Strip(), "squeeze": Squeeze()}
PARAM_STEPS = {"truncate": True}


def lookup(name: str):
    if ":" in name:
        parts = name.split(":", 1)
        step_name = parts[0]
        arg = parts[1]
        if step_name not in BARE_STEPS and step_name not in PARAM_STEPS:
            raise KeyError(f"no step named {step_name!r}. Known: {', '.join(sorted(BARE_STEPS))}")
        if step_name in PARAM_STEPS:
            if arg == "" or not arg.lstrip("-").isdigit():
                raise ValueError(f"invalid argument {arg!r} for step {step_name!r}")
            length = int(arg)
            return Truncate(length)
        return BARE_STEPS[step_name].apply.__self__ if hasattr(BARE_STEPS[step_name].apply, '__self__') else BARE_STEPS[step_name]
    if name == "truncate":
        raise ValueError("step 'truncate' requires a length, e.g. truncate:3")
    if name not in BARE_STEPS:
        raise KeyError(f"no step named {name!r}. Known: {', '.join(sorted(BARE_STEPS))}")
    return BARE_STEPS[name]

